// GENERATED by scripts/bundle-functions.mjs — do not edit by hand.
// Edit supabase/functions/_shared/* and <fn>/source.ts, then re-run the bundler.

// ---------------------------------------------------------------------------
// WorkSense Skill Intelligence Graph engine — the shared, deterministic core.
// Zero LLM calls. Imported by backend functions (Recruitment, Onboarding,
// Recommendation Hub) — never recomputed per page view; results are persisted
// into digital_twins.computed_fits[] and, for skill-match, the durable
// skill_fits table.
//
// Phase 9 (audit rework, engine v3): the score is REQUIREMENT-CENTERED and
// EVIDENCE-CONDITIONED. Every point comes from a requirement being satisfied
// (direct or accepted-adjacent). There is NO global evidence-count component
// and NO seniority component — unrelated evidence or a seniority match can
// never manufacture match points. Evidence quality is an *attenuation factor*
// on each requirement's contribution, and the person's evidence base is
// reported separately (confidence + artifact count) instead of being folded
// into the score.
//
// Two numbers are computed from the same requirement loop:
//   score            = "verified readiness"  — accepted independent evidence
//                      only (reviewer_confirmed / assessment_supported).
//   profile_match    = "provisional profile match" — all live claims, each
//                      attenuated by the evidence factor of its review state.
//
// Mandatory requirements are normalized in their own section and gated: if a
// mandatory requirement has no accepted evidence, mandatory_gate is unmet and
// the readiness is flagged (an unmet mandatory can never raise the number it
// is gated on). Preferred requirements are normalized separately.
// ---------------------------------------------------------------------------

export type VerificationRigor = "low" | "medium" | "high";

/** Bump when the scoring semantics change — stale cached fits are recomputed. */
export const ENGINE_VERSION = "3";

/** Evidence factor by assertion state: how much of a claim's contribution
 *  counts toward the *provisional* profile match. Verified readiness only
 *  accepts the two reviewed states (factor 1). */
export const EVIDENCE_FACTOR: Record<string, number> = {
  reviewer_confirmed: 1,
  assessment_supported: 0.85,
  extracted: 0.5,
  claimed: 0.4,
  // invalidated states never score (expired/disputed/superseded) — factor 0
  expired: 0,
  disputed: 0,
  superseded: 0,
};

/** States treated as accepted, independent evidence. */
export const ACCEPTED_STATES = new Set(["reviewer_confirmed", "assessment_supported"]);

export interface SkillClaim {
  name: string;
  proficiency: number;
  evidence_source: string;
  verification_rigor: VerificationRigor;
}

export type EdgeType = "PREREQUISITE_OF" | "ADJACENT_TO" | "TRANSFERABLE_TO";

export interface GraphEdge {
  target_skill: string;
  type: EdgeType;
  weight: number; // 0.0 - 1.0
}

export interface GraphSkill {
  skill: string;
  category: string;
  outgoing_edges: GraphEdge[];
}

export interface RequiredSkill {
  skill: string;
  target_proficiency: number;
  /** Default true. Preferred criteria are normalized in their own section. */
  mandatory?: boolean;
  /** Optional explicit weight; otherwise normalized equally within the group. */
  criterion_weight?: number;
  /** Explicitly obsolete — removed from the resolved future target. */
  obsolete?: boolean;
}

/**
 * Phase 9: six honest support classifications.
 *  - verified_direct       direct evidence, accepted, at/above target
 *  - provisional_direct    direct evidence, NOT accepted, at/above target
 *  - below_target          direct evidence exists but below the target bar
 *  - adjacent_support      no direct skill; a real ADJACENT_TO edge from a claim
 *  - transferable_foundation  weakest signal: no proficiency, development only
 *  - missing               no direct, adjacent, or transferable path
 */
export type Classification =
  | "verified_direct"
  | "provisional_direct"
  | "below_target"
  | "adjacent_support"
  | "transferable_foundation"
  | "missing";

export type Relationship = "direct" | "adjacent" | "transferable" | "none";

export interface FitItem {
  skill: string;
  classification: Classification;
  relationship: Relationship;
  mandatory: boolean;
  required_proficiency: number;
  /** Observed level (direct claim, or the supporting claim for adjacent). */
  candidate_proficiency: number | null;
  /** The level credit actually applied toward the requirement (0 when none). */
  effective_proficiency: number;
  /** Target minus effective credit, floored at 0. */
  gap: number;
  /** Direct acceptance state of the best supporting assertion (null = none). */
  evidence_state: string | null;
  /** Source artifact key or evidence source behind the best supporting claim. */
  evidence_source: string | null;
  /** Age in days of the newest supporting assertion (null = unknown). */
  freshness_days: number | null;
  /** Evidence factor (0-1) attenuating the provisional credit. */
  evidence_factor: number;
  /** Verified credit (0-1): accepted direct ratio or accepted-adjacent value. */
  verified_contribution: number | null;
  /** Provisional credit (0-1): full credit attenuated by evidence factor. */
  contribution: number | null;
  /** Counts toward verified readiness. */
  verified: boolean;
  /** Counts toward the provisional profile match. */
  provisional: boolean;
  /** Deterministic next action for this requirement. */
  next_action: string;
  edge: { from_skill: string; type: EdgeType; weight: number } | null;
  reason: string;
  /** Honest limitation of this classification (never equivalence). */
  limitation?: string | null;
}

/** One row of the requirement-by-requirement matrix. */
export type RequirementScore = FitItem;

export interface FitRecord {
  target_type: "requisition";
  target_id: string;
  target_title: string;
  scenario: "current" | "future";
  /** Verified readiness (0-1, 3dp) — today's accepted evidence vs the
   *  requirement set this scenario evaluates. */
  score: number;
  /** Provisional profile match (0-1, 3dp) — all live claims, attenuated. */
  profile_match: number;
  /** Weighted mean evidence factor over contributing requirements (0-1). */
  evidence_confidence: number;
  /** Mandatory gate: met only when every mandatory requirement has a
   *  non-zero verified contribution. */
  mandatory_gate: {
    met: boolean;
    unmet_skills: string[];
    count: number;
    note: string;
  };
  /** Seniority is informational context, never part of the score. */
  contextual_alignment: {
    candidate_level: number;
    role_level: number;
    note: string;
  };
  scoring: {
    requirements: RequirementScore[];
    mandatory: { count: number; met: number; unmet: number; unmet_skills: string[]; gated: boolean; readiness: number | null };
    preferred: { count: number; readiness: number | null } | null;
    verified: { readiness: number };
    provisional: { readiness: number };
    confidence: number;
    group_weights: { mandatory: number; preferred: number };
    evidence_artifacts: { count: number; threshold: number };
    resolved_from: "current" | "resolved-future";
    /** For the future scenario: how the evaluated set was derived. */
    derivation?: { kept: string[]; added: string[]; raised: string[]; obsolete: string[] };
  };
  classification: Record<Classification, FitItem[]>;
  versions?: {
    engine: string;
    evidence: string;
    requisition: string;
    graph?: string;
    context?: string;
    plan?: string;
  };
  assumptions?: {
    horizon: string;
    note: string;
  };
  computed_at: string;
}

/** Group weights between the mandatory and preferred sections. Within each
 *  section, requirements are normalized by count (or their criterion_weight). */
export const GROUP_WEIGHTS = {
  mandatory: 0.7,
  preferred: 0.3,
} as const;

/** Informational only (artifact count / evidence confidence) — this is NOT a
 *  score component anymore. Kept for display of the evidence base. */
export const DEFAULT_EVIDENCE_THRESHOLD = 5;

const norm = (s: string) => s.trim().toLowerCase();

export function findEdge(
  skillGraph: GraphSkill[],
  from: string,
  to: string,
  type: EdgeType
): GraphEdge | null {
  const node = skillGraph.find((n) => norm(n.skill) === norm(from));
  const edge = node?.outgoing_edges.find(
    (e) => norm(e.target_skill) === norm(to) && e.type === type
  );
  return edge ?? null;
}

const round3 = (n: number) => Math.round(n * 1000) / 1000;
const mean = (xs: number[]) => (xs.length === 0 ? 0 : xs.reduce((a, b) => a + b, 0) / xs.length);

/** Deterministic FNV-1a hex (uniquely named to avoid bundle collisions). */
export function graphFnv1aHex(str: string): string {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return (h >>> 0).toString(16).padStart(8, "0");
}

/**
 * Version hash over the requisition's skill content. Phase 9: covers the
 * normalized current set, the resolved future set, mandatory/preferred status,
 * target proficiency, criterion weight, seniority target and obsolete list —
 * any change invalidates cached fits.
 */
export function requisitionContentHash(params: {
  current: RequiredSkill[];
  future: RequiredSkill[];
  resolvedFuture: RequiredSkill[];
  seniorityLevel: number;
  obsolete?: RequiredSkill[];
}): string {
  const line = (s: RequiredSkill, tag: string) =>
    `${tag}:${norm(s.skill)}|t${s.target_proficiency}|m${s.mandatory === false ? 0 : 1}|w${s.criterion_weight ?? ""}`;
  const payload = [
    ...(params.current ?? []).map((s) => line(s, "cur")).sort(),
    ...(params.future ?? []).map((s) => line(s, "fut")).sort(),
    ...(params.resolvedFuture ?? []).map((s) => line(s, "res")).sort(),
    ...(params.obsolete ?? []).map((s) => line(s, "obs")).sort(),
    `level:${params.seniorityLevel}`,
  ].join(";");
  return graphFnv1aHex(payload);
}

/** Version hash over the person's resolved skill claims. */
export function claimHash(claims: SkillClaim[]): string {
  const payload = (claims ?? [])
    .map((c) => `${norm(c.name)}|${c.proficiency}|${c.evidence_source}|${c.verification_rigor}`)
    .sort()
    .join(";");
  return graphFnv1aHex(payload);
}

/**
 * Phase 9: the full evidence fingerprint. Covers assertion ids, review states,
 * effective proficiency, evidence ids, artifact keys and captured_at/expiry —
 * so accepting, correcting, rejecting, expiring or replacing any assertion or
 * artifact invalidates every cached fit that depended on it.
 */
export function evidenceDetailHash(lineage: {
  assertions: { id: string; skill_id?: string; claimed_proficiency: number; review_state: string; evidence_ids?: string[]; created_at?: string }[];
  evidence: { id: string; source_type?: string | null; source_id?: string | null; captured_at?: string | null; review_state?: string }[];
}): string {
  const artifactKey = (e: { source_type?: string | null; source_id?: string | null; id: string }) =>
    e.source_id ? `artifact:${e.source_type ?? "unknown"}|${e.source_id}` : `item:${e.id}`;
  const parts = [
    ...(lineage.assertions ?? []).map((a) =>
      `a:${a.id}|s${a.skill_id ?? ""}|p${a.claimed_proficiency}|r${a.review_state}|e[${(a.evidence_ids ?? []).sort().join(",")}]|c${a.created_at ?? ""}`
    ),
    ...(lineage.evidence ?? []).map((e) =>
      `ev:${e.id}|k${artifactKey(e)}|c${e.captured_at ?? ""}|r${e.review_state ?? ""}`
    ),
  ].sort();
  return graphFnv1aHex(parts.join(";"));
}

/** Version hash over the whole graph (nodes + typed edges). */
export function graphContentHash(
  graph: { skill: string; outgoing_edges: { target_skill: string; type: string; weight: number }[] }[]
): string {
  const payload = (graph ?? [])
    .flatMap((n) => [
      `node:${n.skill}`,
      ...(n.outgoing_edges ?? []).map((e) => `${n.skill}|${e.type}|${e.target_skill}|${e.weight}`),
    ])
    .sort()
    .join(";");
  return graphFnv1aHex(payload);
}

/** Person-level context that affects the *display* (contextual alignment,
 *  evidence base) — not the score itself. Kept in the fingerprint so the
 *  cached result is recomputed when this context changes. */
export function personContextHash(candidateLevel: number, evidenceArtifactCount: number | undefined, claimCount: number): string {
  const artifacts = evidenceArtifactCount !== undefined ? evidenceArtifactCount : claimCount;
  return graphFnv1aHex(`level:${candidateLevel}|artifacts:${artifacts}`);
}

export function fitIsStale(
  fit: FitRecord | null,
  current: { engine: string; evidence: string; requisition: string; graph?: string; context?: string; plan?: string }
): boolean {
  if (!fit) return true;
  const v = fit.versions;
  if (!v) return true; // pre-version fits are always stale
  if (v.engine !== current.engine || v.evidence !== current.evidence || v.requisition !== current.requisition) return true;
  if (current.graph !== undefined && (v.graph ?? undefined) !== current.graph) return true;
  if (current.context !== undefined && (v.context ?? undefined) !== current.context) return true;
  if (current.plan !== undefined && (v.plan ?? "none") !== current.plan) return true;
  return false;
}

const HORIZON_LABEL: Record<string, string> = {
  current: "Current requirements — as recorded on the requisition today. Verified readiness answers: how much of today's requirement is already backed by accepted evidence?",
  future: "Resolved 12–24 month target — today's still-relevant requirements plus future additions, with raised targets applied. Verified readiness answers: how much of the future target is already backed by accepted evidence TODAY (no assumed learning)?",
};

/** Map a claim's evidence_source/rigor to {accepted, factor, state}. */
function evidenceMeta(source: string, rigor: VerificationRigor): { accepted: boolean; factor: number; state: string } {
  const s = (source ?? "").toLowerCase();
  if (s === "evidence_review") return { accepted: true, factor: EVIDENCE_FACTOR.reviewer_confirmed, state: "reviewer_confirmed" };
  if (s === "assessment") return { accepted: true, factor: EVIDENCE_FACTOR.assessment_supported, state: "assessment_supported" };
  if (s === "resume_extraction") return { accepted: false, factor: EVIDENCE_FACTOR.extracted, state: "extracted" };
  if (s === "self_report") return { accepted: false, factor: EVIDENCE_FACTOR.claimed, state: "claimed" };
  if (rigor === "high") return { accepted: true, factor: EVIDENCE_FACTOR.reviewer_confirmed, state: "reviewer_confirmed" };
  if (rigor === "medium") return { accepted: true, factor: EVIDENCE_FACTOR.assessment_supported, state: "assessment_supported" };
  return { accepted: false, factor: EVIDENCE_FACTOR.claimed, state: "claimed" };
}

/** Dedup claims per skill (case-insensitive), keeping the strongest evidence
 *  first, then the highest proficiency. Defends against legacy duplicates. */
function dedupeClaims(claims: SkillClaim[]): SkillClaim[] {
  const best = new Map<string, SkillClaim>();
  for (const c of claims ?? []) {
    const key = norm(c.name);
    if (!key) continue;
    const cur = best.get(key);
    const rank = (x: SkillClaim) => {
      const m = evidenceMeta(x.evidence_source, x.verification_rigor);
      return m.accepted ? (m.factor === 1 ? 3 : 2) : 1;
    };
    if (!cur || rank(c) > rank(cur) || (rank(c) === rank(cur) && c.proficiency > cur.proficiency)) {
      best.set(key, c);
    }
  }
  return [...best.values()];
}

const NEXT_ACTION: Record<Classification, string> = {
  verified_direct: "None — requirement met with accepted evidence.",
  provisional_direct: "Verify evidence — accepted evidence would confirm this match.",
  below_target: "Close the gap to the target level, then re-verify.",
  adjacent_support: "Capability in the required skill itself is not yet evidenced — confirm via an assessment.",
  transferable_foundation: "No proficiency yet — a development candidate, not capability.",
  missing: "No evidence or path — needs an assessment or structured learning.",
};

/** Age of the newest supporting assertion in days (null when unknown). */
function freshnessDays(capturedAt: string | null | undefined, computedAt: string | undefined): number | null {
  if (!capturedAt) return null;
  const now = computedAt ? new Date(computedAt).getTime() : Date.now();
  const then = new Date(capturedAt).getTime();
  if (Number.isNaN(then)) return null;
  return Math.max(0, Math.round((now - then) / 86400000));
}

function evaluateRequirement(
  req: RequiredSkill,
  claims: SkillClaim[],
  graph: GraphSkill[],
  evidenceDetail: Record<string, { captured_at?: string | null; artifact_key?: string | null }>,
  computedAt: string | undefined
): FitItem {
  const target = req.target_proficiency;
  const mandatory = req.mandatory !== false;
  const detail = evidenceDetail?.[norm(req.skill)];

  // ---- Direct claim for the required skill ----
  const own = claims.find((s) => norm(s.name) === norm(req.skill));
  if (own) {
    const meta = evidenceMeta(own.evidence_source, own.verification_rigor);
    const ratio = Math.min(1, own.proficiency / target);
    const verifiedContribution = meta.accepted ? ratio : 0;
    const provisionalContribution = ratio * meta.factor;
    const effective = Math.min(own.proficiency, target);
    const classification: Classification =
      own.proficiency >= target
        ? meta.accepted
          ? "verified_direct"
          : "provisional_direct"
        : "below_target";
    return {
      skill: req.skill,
      classification,
      relationship: "direct",
      mandatory,
      required_proficiency: target,
      candidate_proficiency: own.proficiency,
      effective_proficiency: effective,
      gap: Math.max(0, target - effective),
      evidence_state: meta.state,
      evidence_source: detail?.artifact_key ?? meta.state,
      freshness_days: freshnessDays(detail?.captured_at, computedAt),
      evidence_factor: meta.factor,
      verified_contribution: round3(verifiedContribution),
      contribution: round3(provisionalContribution),
      verified: verifiedContribution > 0,
      provisional: true,
      next_action: NEXT_ACTION[classification],
      edge: null,
      reason: `Holds ${req.skill} at ${own.proficiency}/${target} required — evidence state: ${meta.state}.`,
      limitation: null,
    };
  }

  // ---- Adjacent: no direct skill, but a real ADJACENT_TO edge from a claim ----
  let bestAdj: { from: string; edge: GraphEdge; value: number; claim: SkillClaim } | null = null;
  for (const claim of claims) {
    const edge = findEdge(graph, claim.name, req.skill, "ADJACENT_TO");
    if (edge) {
      const value = Math.min(1, (claim.proficiency / 5) * edge.weight);
      if (!bestAdj || value > bestAdj.value) bestAdj = { from: claim.name, edge, value, claim };
    }
  }
  if (bestAdj) {
    const meta = evidenceMeta(bestAdj.claim.evidence_source, bestAdj.claim.verification_rigor);
    const verifiedContribution = meta.accepted ? bestAdj.value : 0;
    const provisionalContribution = bestAdj.value * meta.factor;
    const effective = Math.min(bestAdj.value * target, target);
    return {
      skill: req.skill,
      classification: "adjacent_support",
      relationship: "adjacent",
      mandatory,
      required_proficiency: target,
      candidate_proficiency: bestAdj.claim.proficiency,
      effective_proficiency: round3(effective),
      gap: round3(Math.max(0, target - effective)),
      evidence_state: meta.state,
      evidence_source: detail?.artifact_key ?? meta.state,
      freshness_days: freshnessDays(detail?.captured_at, computedAt),
      evidence_factor: meta.factor,
      verified_contribution: round3(verifiedContribution),
      contribution: round3(provisionalContribution),
      verified: verifiedContribution > 0,
      provisional: true,
      next_action: NEXT_ACTION.adjacent_support,
      edge: { from_skill: bestAdj.from, type: "ADJACENT_TO", weight: bestAdj.edge.weight },
      reason: `No direct ${req.skill}; backed by ${bestAdj.from} → ${req.skill} (ADJACENT_TO, ${bestAdj.edge.weight.toFixed(2)}).`,
      limitation: "Adjacent support is NOT direct equivalence: this person has no evidence for the required skill itself. Confirm real capability before relying on it.",
    };
  }

  // ---- Transferable: no direct/adjacent edge, but a TRANSFERABLE_TO edge or
  //      strong same-category relationship. Never contributes points. ----
  let transfer: { from: string; edge: GraphEdge | null; via: string } | null = null;
  for (const claim of claims) {
    const edge = findEdge(graph, claim.name, req.skill, "TRANSFERABLE_TO");
    if (edge) {
      transfer = { from: claim.name, edge, via: "edge" };
      break;
    }
    if (!transfer) {
      const ownNode = graph.find((n) => norm(n.skill) === norm(claim.name));
      const reqNode = graph.find((n) => norm(n.skill) === norm(req.skill));
      if (ownNode && reqNode && ownNode.category && ownNode.category === reqNode.category) {
        transfer = { from: claim.name, edge: null, via: `same category (${ownNode.category})` };
      }
    }
  }
  if (transfer) {
    return {
      skill: req.skill,
      classification: "transferable_foundation",
      relationship: "transferable",
      mandatory,
      required_proficiency: target,
      candidate_proficiency: null,
      effective_proficiency: 0,
      gap: target,
      evidence_state: null,
      evidence_source: null,
      freshness_days: null,
      evidence_factor: 0,
      verified_contribution: 0,
      contribution: 0,
      verified: false,
      provisional: false,
      next_action: NEXT_ACTION.transferable_foundation,
      edge: transfer.edge
        ? { from_skill: transfer.from, type: "TRANSFERABLE_TO", weight: transfer.edge.weight }
        : null,
      reason: transfer.edge
        ? `No direct or adjacent path; ${transfer.from} → ${req.skill} is transferable.`
        : `No direct or adjacent path; ${transfer.from} shares the ${transfer.via}.`,
      limitation: "Transferable support is the weakest signal: it establishes no proficiency in the required skill and contributes no points to the score. Treat it as a development candidate, not capability.",
    };
  }

  // ---- Missing ----
  return {
    skill: req.skill,
    classification: "missing",
    relationship: "none",
    mandatory,
    required_proficiency: target,
    candidate_proficiency: null,
    effective_proficiency: 0,
    gap: target,
    evidence_state: null,
    evidence_source: null,
    freshness_days: null,
    evidence_factor: 0,
    verified_contribution: 0,
    contribution: 0,
    verified: false,
    provisional: false,
    next_action: NEXT_ACTION.missing,
    edge: null,
    reason: `No direct, adjacent, or transferable path found for ${req.skill}.`,
    limitation: null,
  };
}

/** Build the canonical requirement list for a scenario. For "future" the
 *  caller passes the RESOLVED future target (see resolveFutureRequirements).
 *  Defaults: skills carry mandatory=true unless flagged. */
export function normalizeRequirements(skills: RequiredSkill[]): RequiredSkill[] {
  const seen = new Map<string, RequiredSkill>();
  for (const s of skills ?? []) {
    const key = norm(s.skill);
    if (!key) continue;
    seen.set(key, {
      skill: s.skill,
      target_proficiency: s.target_proficiency,
      mandatory: s.mandatory !== false,
      criterion_weight: s.criterion_weight,
      obsolete: s.obsolete,
    });
  }
  return [...seen.values()];
}

/**
 * Phase 9: the resolved 12–24 month target.
 *   = current requirements (minus explicitly-obsolete) + future additions,
 *     with future targets applied (raised targets raise, additions are future
 *     capability signals → preferred).
 * A current skill missing from the future list is KEPT unless explicitly
 * marked obsolete — removals only happen on explicit intent.
 */
export function resolveFutureRequirements(
  current: RequiredSkill[],
  future: RequiredSkill[],
  obsolete: RequiredSkill[] = []
): { resolved: RequiredSkill[]; kept: string[]; added: string[]; raised: string[]; obsolete: string[] } {
  const curList = normalizeRequirements(current);
  const futList = normalizeRequirements(future);
  const obsKeys = new Set(normalizeRequirements(obsolete).map((o) => norm(o.skill)));
  const curMap = new Map(curList.map((r) => [norm(r.skill), r]));
  const futMap = new Map(futList.map((r) => [norm(r.skill), r]));

  const resolved: RequiredSkill[] = [];
  const kept: string[] = [];
  const added: string[] = [];
  const raised: string[] = [];

  for (const cur of curList) {
    const key = norm(cur.skill);
    if (obsKeys.has(key)) continue;
    const fut = futMap.get(key);
    if (fut) {
      resolved.push({ ...cur, target_proficiency: fut.target_proficiency });
      if (fut.target_proficiency > cur.target_proficiency) raised.push(cur.skill);
      else kept.push(cur.skill);
    } else {
      resolved.push(cur);
      kept.push(cur.skill);
    }
  }
  for (const fut of futList) {
    const key = norm(fut.skill);
    if (curMap.has(key)) continue;
    resolved.push({ ...fut, mandatory: false }); // future capability signal
    added.push(fut.skill);
  }
  return { resolved, kept, added, raised, obsolete: [...obsKeys] };
}

export function computeFit(params: {
  candidateSkills: SkillClaim[];
  candidateLevel: number;
  requiredSkills: RequiredSkill[];
  roleLevel: number;
  skillGraph: GraphSkill[];
  threshold?: number;
  target: { type: "requisition"; id: string; title: string };
  scenario: "current" | "future";
  computedAt?: string;
  /** Distinct artifact count behind the claims (display only now). */
  evidenceArtifactCount?: number;
  /** Per-requirement evidence detail (freshness / artifact source). */
  evidenceDetail?: Record<string, { captured_at?: string | null; artifact_key?: string | null }>;
  /** Pre-computed evidence fingerprint (superset of claimHash). */
  evidenceVersion?: string;
  /** Requisition content hash (stale detection). */
  requisitionVersion?: string;
  /** Optional development-plan version; "none" when no plan is approved. */
  planVersion?: string;
  /** Derivation metadata for the future scenario. */
  derivation?: { kept: string[]; added: string[]; raised: string[]; obsolete: string[] };
}): FitRecord {
  const threshold = params.threshold ?? DEFAULT_EVIDENCE_THRESHOLD;
  const claims = dedupeClaims(params.candidateSkills);
  const required = normalizeRequirements(params.requiredSkills ?? []);
  const computedAt = params.computedAt ?? new Date().toISOString();

  const items: FitItem[] = required.map((r) =>
    evaluateRequirement(r, claims, params.skillGraph, params.evidenceDetail ?? {}, computedAt)
  );

  const mandatoryItems = items.filter((i) => i.mandatory);
  const preferredItems = items.filter((i) => !i.mandatory);

  const groupVerified = (list: FitItem[]) =>
    list.length === 0 ? null : mean(list.map((i) => i.verified_contribution ?? 0));
  const groupProvisional = (list: FitItem[]) =>
    list.length === 0 ? null : mean(list.map((i) => i.contribution ?? 0));

  const mVerified = groupVerified(mandatoryItems);
  const pVerified = groupVerified(preferredItems);
  const mProvisional = groupProvisional(mandatoryItems);
  const pProvisional = groupProvisional(preferredItems);

  const { mandatory: wM, preferred: wP } = GROUP_WEIGHTS;
  const verifiedReadiness =
    mVerified !== null && pVerified !== null
      ? wM * mVerified + wP * pVerified
      : mVerified ?? pVerified ?? 0;
  const provisionalReadiness =
    mProvisional !== null && pProvisional !== null
      ? wM * mProvisional + wP * pProvisional
      : mProvisional ?? pProvisional ?? 0;

  // Evidence confidence: weighted mean factor over requirements with any
  // contribution — a measure of the evidence BASE, not a score component.
  const contributing = items.filter((i) => (i.contribution ?? 0) > 0);
  const confidence = contributing.length === 0 ? 0 : mean(contributing.map((i) => i.evidence_factor));

  // Mandatory gate: every mandatory requirement needs accepted evidence.
  const unmetMandatory = mandatoryItems.filter((i) => (i.verified_contribution ?? 0) <= 0);
  const gate = {
    met: unmetMandatory.length === 0,
    unmet_skills: unmetMandatory.map((i) => i.skill),
    count: mandatoryItems.length,
    note:
      unmetMandatory.length === 0
        ? mandatoryItems.length === 0
          ? "No mandatory criteria are defined for this demand."
          : "Every mandatory requirement has accepted evidence (direct or accepted-adjacent)."
        : `Unmet: ${unmetMandatory.map((i) => i.skill).join(", ")}. Without accepted evidence these cannot raise verified readiness.`,
  };

  const classification: Record<Classification, FitItem[]> = {
    verified_direct: items.filter((i) => i.classification === "verified_direct"),
    provisional_direct: items.filter((i) => i.classification === "provisional_direct"),
    below_target: items.filter((i) => i.classification === "below_target"),
    adjacent_support: items.filter((i) => i.classification === "adjacent_support"),
    transferable_foundation: items.filter((i) => i.classification === "transferable_foundation"),
    missing: items.filter((i) => i.classification === "missing"),
  };

  const evidenceVersion = params.evidenceVersion ?? claimHash(claims);
  const artifactCount =
    params.evidenceArtifactCount !== undefined
      ? params.evidenceArtifactCount
      : claims.filter((s) => s.verification_rigor === "high" || s.verification_rigor === "medium").length;

  return {
    target_type: params.target.type,
    target_id: params.target.id,
    target_title: params.target.title,
    scenario: params.scenario,
    score: round3(verifiedReadiness),
    profile_match: round3(provisionalReadiness),
    evidence_confidence: round3(confidence),
    mandatory_gate: gate,
    contextual_alignment: {
      candidate_level: params.candidateLevel,
      role_level: params.roleLevel,
      note: `Seniority (${params.candidateLevel} vs ${params.roleLevel} role level) is shown as context only — it never contributes to the match score.`,
    },
    scoring: {
      requirements: items,
      mandatory: {
        count: mandatoryItems.length,
        met: mandatoryItems.length - unmetMandatory.length,
        unmet: unmetMandatory.length,
        unmet_skills: unmetMandatory.map((i) => i.skill),
        gated: unmetMandatory.length > 0,
        readiness: mVerified === null ? null : round3(mVerified),
      },
      preferred: preferredItems.length === 0 ? null : { count: preferredItems.length, readiness: pVerified === null ? null : round3(pVerified) },
      verified: { readiness: round3(verifiedReadiness) },
      provisional: { readiness: round3(provisionalReadiness) },
      confidence: round3(confidence),
      group_weights: { mandatory: wM, preferred: wP },
      evidence_artifacts: { count: artifactCount, threshold },
      resolved_from: params.scenario === "future" ? "resolved-future" : "current",
      ...(params.derivation ? { derivation: params.derivation } : {}),
    },
    classification,
    versions: {
      engine: ENGINE_VERSION,
      evidence: evidenceVersion,
      requisition: params.requisitionVersion ?? "unknown",
      graph: graphContentHash(params.skillGraph),
      context: personContextHash(params.candidateLevel, params.evidenceArtifactCount, claims.length),
      plan: params.planVersion ?? "none",
    },
    assumptions: {
      horizon: params.scenario === "future" ? "Resolved 12–24 month target" : "Current",
      note: HORIZON_LABEL[params.scenario],
    },
    computed_at: computedAt,
  };
}

/** Cache key for computed_fits[] entries. */
export function fitKey(record: { target_type: string; target_id: string; scenario: string }) {
  return `${record.target_type}|${record.target_id}|${record.scenario}`;
}

/**
 * Skill-match authorization — a pure, role-scoped decision shared by the
 * backend function (server enforcement) and unit tests. Deliberately does not
 * decide ownership on the client.
 *
 * Scopes:
 *   org        — administrator (any twin) / HR partner (workforce twins only)
 *   candidates — recruiter (candidate twins only)
 *   team       — manager (direct/recursive reports, self handled separately)
 *   self       — manager self / employee self
 *   denied     — everything else (IT, candidate callers, cross-org, out of scope)
 */
export type SkillMatchScope = "org" | "candidates" | "team" | "self" | "denied";

export interface AuthorizeSkillMatchArgs {
  callerRole: string;
  callerOrgId: string;
  callerTwinId: string;
  targetOrgId: string;
  targetTwinId: string;
  targetRole: string;
  /** Pre-resolved subtree check (manager only); a failed lookup must be false. */
  targetIsInCallerTeam: boolean;
}

export function authorizeSkillMatch(args: AuthorizeSkillMatchArgs): SkillMatchScope {
  const { callerRole, callerOrgId, callerTwinId, targetOrgId, targetTwinId, targetRole, targetIsInCallerTeam } = args;
  if (!callerOrgId || targetOrgId !== callerOrgId) return "denied";

  if (callerRole === "hr_executive") return "org";
  if (callerRole === "hr_partner") return targetRole === "candidate" ? "denied" : "org";
  if (callerRole === "recruiter") return targetRole === "candidate" ? "candidates" : "denied";
  if (callerRole === "manager") {
    if (targetTwinId === callerTwinId) return "self";
    return targetIsInCallerTeam ? "team" : "denied";
  }
  if (callerRole === "employee") {
    return targetTwinId === callerTwinId ? "self" : "denied";
  }
  return "denied";
}


// ---------------------------------------------------------------------------
// WorkSense Phase 8 onboarding engine — fully deterministic, zero LLM.
//  - Task definition vs execution state (separate column groups)
//  - Strict owner matrix: employee | manager | hr | it_security (no broad HR
//    to service owners)
//  - DAG planning from the APPROVED role relationship (application ->
//    requisition), never a title substring
//  - Cycle / missing-dep validation + Kahn topological scheduling
//  - Blocked set (multiple simultaneous blockers) + critical path
//  - Honest readiness estimate (never a guarantee)
//  - plan_hash bound to canonical task definitions (approvals bind to it)
//  - Waiver, adaptation (learning -> verification, failed verification reopens
//    gap), completion checks as PURE functions so backend functions just
//    load rows and apply them.
// ---------------------------------------------------------------------------

export type OwnerRole = "employee" | "manager" | "hr" | "it_security";
export type TaskType = "learning" | "verification" | "provisioning" | "policy" | "access" | "onboarding_admin";
export type TaskState = "pending" | "blocked" | "ready" | "in_progress" | "done" | "waived" | "failed";
export type PlanStatus = "draft" | "pending_approval" | "approved" | "completed" | "superseded";

export interface WhyEvidence {
  reason: string;
  source_evidence: { source_type: string; fact: string; ref?: string }[];
}

export interface EvReq {
  kind: "note" | "assessment_id";
  label: string;
  required: boolean;
}

/** Immutable task DEFINITION — what needs to happen. */
export interface TaskDef {
  task_code: string;
  title: string;
  task_type: TaskType;
  owner_role: OwnerRole;
  required: boolean;
  non_waivable: boolean;
  depends_on: string[];
  duration_days: number;
  why_evidence: WhyEvidence;
  evidence_requirements: EvReq[];
}

export interface Blocker {
  id: string;
  note: string;
  reported_by: string;
  at: string;
  status: "open" | "resolved";
  resolved_by?: string;
  resolved_at?: string;
}

export interface Waiver {
  by_twin_id: string;
  by_name: string;
  reason: string;
  policy_basis: { doc_code: string; version: number | null } | null;
  at: string;
}

export interface CompletionRecord {
  actor_twin_id: string;
  actor_name: string;
  at: string;
  evidence: { kind: "note" | "assessment_id"; label: string; value: string }[];
  attempt_hash: string;
  note?: string;
}

export interface Adaptation {
  kind: "replaced" | "reopened_gap";
  replaced_by?: string;
  reason: string;
  source_evidence: WhyEvidence["source_evidence"];
  at: string;
  actor_twin_id: string;
}

/** Task DEFINITION + EXECUTION state. */
export interface PlanTask extends TaskDef {
  state: TaskState;
  start_date: string | null;
  due_date: string | null;
  topological_level: number;
  blocked_reasons: string[]; // task_codes of unmet deps
  blockers: Blocker[];
  waiver: Waiver | null;
  completion_record: CompletionRecord | null;
  adaptation: Adaptation | null;
}

export interface ReadinessDimension {
  key: "access" | "compliance" | "capability";
  label: string;
  /** satisfied = done (or waived for access/compliance; waived NEVER counts as
   *  capability — a waived task must not imply a skill was verified). */
  satisfied: number;
  total: number;
  pct: number;
  note: string;
}

export interface ReadinessEstimate {
  /** Overall task completion (done + waived). */
  ready_pct: number;
  satisfied: number;
  total: number;
  /** Remaining critical path, in duration-days (not node count). */
  remaining_critical_days: number;
  /** Business-day projection from today; null when blockers make it unknown. */
  projected_ready_date: string | null;
  blocked_count: number;
  note: string;
  /** True when the projection is provisional (open blockers on the path). */
  provisional: boolean;
  /** Remaining critical path as task codes (ordered, by duration). */
  critical_path: string[];
  /** Access / compliance / role-capability readiness shown separately from
   *  overall completion. */
  dimensions: ReadinessDimension[];
  working_calendar: "business_days";
}

export interface CarryoverEntry {
  task_code: string;
  from_version: number;
  from_plan_id: string;
  note: string;
}

export class CycleError extends Error {
  constructor(message = "cyclic dependency detected in onboarding plan") {
    super(message);
    this.name = "CycleError";
  }
}

// ---------------------------------------------------------------------------
// Hashing (deterministic, sync; binding approval to exact task definitions)
// ---------------------------------------------------------------------------

function fnv1a(str: string, seed = 0x811c9dc5): number {
  let h = seed >>> 0;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return h >>> 0;
}

/** Stable hash of canonical task definitions — same defs always hash equal. */
export function planHash(defs: TaskDef[]): string {
  const canonical = defs
    .map((d) =>
      JSON.stringify({
        code: d.task_code,
        title: d.title,
        type: d.task_type,
        owner: d.owner_role,
        required: d.required,
        non_waivable: d.non_waivable,
        deps: [...d.depends_on].sort(),
        days: d.duration_days,
        why: d.why_evidence,
        evreq: d.evidence_requirements,
      })
    )
    .sort()
    .join("\u0001");
  const h1 = fnv1a(canonical).toString(16).padStart(8, "0");
  const h2 = fnv1a(canonical, 0x811c9dc5 ^ canonical.length).toString(16).padStart(8, "0");
  return `${h1}${h2}`;
}

/** Attempt hash for execution dedup: same actor+payload on same task+action. */
export function attemptHash(planId: string, taskCode: string, action: string, payload: unknown): string {
  const canonical = JSON.stringify({ planId, taskCode, action, payload });
  const h1 = fnv1a(canonical).toString(16).padStart(8, "0");
  const h2 = fnv1a(canonical, 0xdeadbeef).toString(16).padStart(8, "0");
  return `${h1}${h2}`;
}

// ---------------------------------------------------------------------------
// DAG validation + topological scheduling
// ---------------------------------------------------------------------------

export function validateDag(defs: TaskDef[]): void {
  const ids = new Set(defs.map((d) => d.task_code));
  for (const d of defs) {
    for (const dep of d.depends_on) {
      if (!ids.has(dep)) throw new Error(`task ${d.task_code} depends on unknown task ${dep}`);
    }
  }
  const indegree = new Map(defs.map((d) => [d.task_code, d.depends_on.length]));
  const adj = new Map<string, string[]>();
  for (const d of defs) {
    for (const dep of d.depends_on) adj.set(dep, [...(adj.get(dep) ?? []), d.task_code]);
  }
  const queue = defs.filter((d) => (indegree.get(d.task_code) ?? 0) === 0).map((d) => d.task_code);
  const order: string[] = [];
  while (queue.length > 0) {
    const id = queue.shift()!;
    order.push(id);
    for (const child of adj.get(id) ?? []) {
      indegree.set(child, (indegree.get(child) ?? 0) - 1);
      if ((indegree.get(child) ?? 0) === 0) queue.push(child);
    }
  }
  if (order.length !== defs.length) throw new CycleError();
}

const DAY_MS = 24 * 60 * 60 * 1000;
function addDays(d: Date, days: number): Date {
  return new Date(d.getTime() + days * DAY_MS);
}

export function topologicalOrder(defs: TaskDef[]): string[] {
  validateDag(defs);
  const indegree = new Map(defs.map((d) => [d.task_code, d.depends_on.length]));
  const adj = new Map<string, string[]>();
  for (const d of defs) {
    for (const dep of d.depends_on) adj.set(dep, [...(adj.get(dep) ?? []), d.task_code]);
  }
  const queue = defs.filter((d) => (indegree.get(d.task_code) ?? 0) === 0).map((d) => d.task_code);
  const order: string[] = [];
  while (queue.length > 0) {
    const id = queue.shift()!;
    order.push(id);
    for (const child of adj.get(id) ?? []) {
      indegree.set(child, (indegree.get(child) ?? 0) - 1);
      if ((indegree.get(child) ?? 0) === 0) queue.push(child);
    }
  }
  return order;
}

/** Satisfied = done or waived. Used for both state derivation and critical path. */
export function satisfiedSet(tasks: Pick<PlanTask, "task_code" | "state">[]): Set<string> {
  return new Set(tasks.filter((t) => t.state === "done" || t.state === "waived").map((t) => t.task_code));
}

export function hasOpenBlocker(blockers: Blocker[]): boolean {
  return blockers.some((b) => b.status === "open");
}

/**
 * Recompute execution state + dates from stored facts (definition + state).
 * Dates are null for blocked/failed tasks and cascade downstream.
 */
export function deriveStates(defs: TaskDef[], facts: {
  done?: string[];
  waived?: string[];
  failed?: string[];
  blockers?: Record<string, Blocker[]>;
  approved?: boolean;
  startDate?: string;
}): PlanTask[] {
  validateDag(defs);
  const done = new Set(facts.done ?? []);
  const waived = new Set(facts.waived ?? []);
  const failed = new Set(facts.failed ?? []);
  const approved = facts.approved ?? false;
  const start = facts.startDate ? new Date(facts.startDate) : new Date();

  const order = topologicalOrder(defs);
  const defById = new Map(defs.map((d) => [d.task_code, d]));

  const level = new Map<string, number>();
  for (const id of order) {
    const d = defById.get(id)!;
    level.set(id, d.depends_on.reduce((m, dep) => Math.max(m, (level.get(dep) ?? 0) + 1), 0));
  }

  const endBy = new Map<string, Date | null>();
  const out = new Map<string, PlanTask>();
  for (const id of order) {
    const d = defById.get(id)!;
    const blockers = facts.blockers?.[id] ?? [];
    const open = hasOpenBlocker(blockers);
    const depStates = new Map(d.depends_on.map((dep) => [dep, out.get(dep)?.state ?? "missing"]));
    const unmet = d.depends_on.filter((dep) => !done.has(dep) && !waived.has(dep));
    const cascadingBlock = d.depends_on.some((dep) => {
      const s = depStates.get(dep);
      return s === "blocked" || s === "failed";
    });

    let state: TaskState = "pending";
    if (done.has(id)) state = "done";
    else if (waived.has(id)) state = "waived";
    else if (failed.has(id)) state = "failed";
    else if (!approved) state = "pending";
    else if (open) state = "blocked";
    else if (cascadingBlock) state = "blocked";
    else if (unmet.length > 0) state = "pending"; // queued: approved but deps not yet satisfied
    else state = "ready";

    let startDate: Date | null;
    let endDate: Date | null;
    if (state === "blocked" || state === "failed") {
      startDate = null;
      endDate = null;
    } else {
      const prereqEnds = d.depends_on
        .map((dep) => endBy.get(dep))
        .filter((e): e is Date => e instanceof Date);
      const base = prereqEnds.length > 0 ? new Date(Math.max(...prereqEnds.map((e) => e.getTime()))) : new Date(start);
      startDate = base;
      endDate = addDays(base, d.duration_days);
    }
    endBy.set(id, endDate);

    out.set(id, {
      ...d,
      state,
      start_date: startDate ? startDate.toISOString() : null,
      due_date: endDate ? endDate.toISOString() : null,
      topological_level: level.get(id) ?? 0,
      blocked_reasons: unmet,
      blockers,
      waiver: null,
      completion_record: null,
      adaptation: null,
    });
  }
  return [...out.values()];
}

/** Apply stored execution records onto derived states (single source of truth). */
export function materialize(tasks: PlanTask[], records: {
  completion?: Record<string, CompletionRecord>;
  waiver?: Record<string, Waiver>;
  adaptation?: Record<string, Adaptation>;
  blockers?: Record<string, Blocker[]>;
}): PlanTask[] {
  return tasks.map((t) => ({
    ...t,
    state: records.waiver?.[t.task_code]
      ? "waived"
      : records.completion?.[t.task_code]
        ? "done"
        : records.adaptation?.[t.task_code]
          ? "failed"
          : t.state,
    blockers: records.blockers?.[t.task_code] ?? t.blockers,
    waiver: records.waiver?.[t.task_code] ?? t.waiver,
    completion_record: records.completion?.[t.task_code] ?? t.completion_record,
    adaptation: records.adaptation?.[t.task_code] ?? t.adaptation,
  }));
}

// ---------------------------------------------------------------------------
// Critical path + honest readiness estimate
// ---------------------------------------------------------------------------

/** Longest remaining chain (by duration) among tasks that are not satisfied. */
export function criticalPath(defs: TaskDef[], satisfied: Set<string>): { tasks: string[]; total_days: number } {
  validateDag(defs);
  const defById = new Map(defs.map((d) => [d.task_code, d]));
  const adj = new Map<string, string[]>();
  for (const d of defs) for (const dep of d.depends_on) adj.set(dep, [...(adj.get(dep) ?? []), d.task_code]);

  const memo = new Map<string, { tasks: string[]; days: number }>();
  const chainFrom = (id: string): { tasks: string[]; days: number } => {
    const known = memo.get(id);
    if (known) return known;
    const d = defById.get(id)!;
    let best: { tasks: string[]; days: number } = { tasks: [], days: 0 };
    for (const child of adj.get(id) ?? []) {
      const c = chainFrom(child);
      if (c.days > best.days) best = c;
    }
    const res = { tasks: [id, ...best.tasks], days: d.duration_days + best.days };
    memo.set(id, res);
    return res;
  };

  let best: { tasks: string[]; days: number } = { tasks: [], days: 0 };
  for (const d of defs) {
    if (satisfied.has(d.task_code)) continue;
    const c = chainFrom(d.task_code);
    if (c.days > best.days) best = c;
  }
  return { tasks: best.tasks, total_days: best.days };
}

/** Business-day calendar: duration days map onto working days only. */
function addBusinessDays(start: Date, workingDays: number): Date {
  const d = new Date(start);
  let remaining = workingDays;
  while (remaining > 0) {
    d.setUTCDate(d.getUTCDate() + 1);
    const dow = d.getUTCDay();
    if (dow === 0 || dow === 6) continue; // weekend
    remaining -= 1;
  }
  return d;
}

/**
 * Honest readiness: overall task completion shown SEPARATELY from access,
 * compliance and role-capability readiness. The critical path uses remaining
 * durations (business days) over prerequisites — never the longest node chain.
 * Blockers on the path make the projection provisional (unknown date); waived
 * learning/verification tasks never count as capability.
 */
export function estimateReadiness(defs: TaskDef[], tasks: PlanTask[], startDate: string, now: string): ReadinessEstimate {
  const satisfied = satisfiedSet(tasks);
  const total = defs.length;
  const readyPct = total === 0 ? 0 : Math.round((satisfied.size / total) * 1000) / 10;
  const { tasks: path, total_days } = criticalPath(defs, satisfied);
  const blockedCount = tasks.filter((t) => t.state === "blocked" || t.state === "failed").length;

  // A blocker on any remaining critical-path task means the date is unknown,
  // not confidently projected — label the estimate provisional (spec: forecast
  // dates must account for blockers; label provisional estimates).
  const openOnPath = path.filter((code) => tasks.find((t) => t.task_code === code)?.blockers.some((b) => b.status === "open"));
  const provisional = openOnPath.length > 0;
  const projected = total_days === 0 ? null : provisional ? null : addBusinessDays(new Date(now), total_days).toISOString();

  const dimensionFor = (key: ReadinessDimension["key"], types: TaskType[], countWaived: boolean): ReadinessDimension => {
    const members = tasks.filter((t) => types.includes(t.task_type));
    const sat = members.filter((t) => t.state === "done" || (countWaived && t.state === "waived")).length;
    const pct = members.length === 0 ? 100 : Math.round((sat / members.length) * 1000) / 10;
    return {
      key,
      label: key === "access" ? "Access readiness" : key === "compliance" ? "Compliance readiness" : "Role capability",
      satisfied: sat,
      total: members.length,
      pct,
      note:
        key === "capability"
          ? "Waived tasks never count as verified skill — capability needs a completed learning or verification task."
          : key === "access"
            ? "Provisioning and system-access tasks complete the technical floor."
            : "Mandatory policy tasks are done before systems stay open.",
    };
  };

  const dimensions: ReadinessDimension[] = [
    dimensionFor("access", ["provisioning", "access"], true),
    dimensionFor("compliance", ["policy"], true),
    dimensionFor("capability", ["learning", "verification"], false),
  ];

  const note = provisional
    ? `Estimated readiness — ${openOnPath.length} blocker(s) remain on the critical path, so the ready date is unknown until they clear. Blocked work makes this provisional, not a guarantee.`
    : "Estimated readiness — projected earliest completion in business days from today; an estimate, not a guarantee.";

  return {
    ready_pct: readyPct,
    satisfied: satisfied.size,
    total,
    remaining_critical_days: total_days,
    projected_ready_date: projected,
    blocked_count: blockedCount,
    note,
    provisional,
    critical_path: path,
    dimensions,
    working_calendar: "business_days",
  };
}

// ---------------------------------------------------------------------------
// Authorization matrix — strict per-owner-role, no broad HR to service owners
// ---------------------------------------------------------------------------

export function canActOnTask(actor: { id: string; role: string; org_id: string | null }, taskOwner: OwnerRole, twin: { id: string; manager_id: string | null; org_id: string | null }): { ok: boolean; error?: string } {
  if (actor.org_id !== twin.org_id) return { ok: false, error: "Cross-org task access is forbidden." };
  switch (taskOwner) {
    case "employee":
      return actor.id === twin.id
        ? { ok: true }
        : { ok: false, error: "Only the employee themselves may complete this task." };
    case "manager":
      return actor.role === "manager" && actor.id === twin.manager_id
        ? { ok: true }
        : { ok: false, error: "Only the employee's direct manager may act on this task." };
    case "hr":
      return actor.role === "hr_executive" || actor.role === "hr_partner"
        ? { ok: true }
        : { ok: false, error: "Only HR may act on this task." };
    case "it_security":
      return actor.role === "it_security"
        ? { ok: true }
        : { ok: false, error: "Only the IT security service owner may act on this task — HR has no access to service-owner tasks." };
    default:
      return { ok: false, error: "Unknown owner role." };
  }
}

export function canWaive(actor: { id: string; role: string }, twin: { manager_id: string | null }, taskNonWaivable: boolean, taskOwner: OwnerRole): { ok: boolean; error?: string } {
  if (taskNonWaivable) {
    return actor.role === "hr_executive"
      ? { ok: true }
      : { ok: false, error: "Non-waivable tasks may only be waived by an HR Executive with a policy basis." };
  }
  if (actor.role === "manager" && actor.id === twin.manager_id) return { ok: true };
  if (actor.role === "hr_executive" || actor.role === "hr_partner") return { ok: true };
  return { ok: false, error: "Waivers require the employee's manager or an HR role." };
}

export function canAdapt(actor: { id: string; role: string }, twin: { manager_id: string | null }): { ok: boolean; error?: string } {
  if (actor.role === "manager" && actor.id === twin.manager_id) return { ok: true };
  if (actor.role === "hr_executive" || actor.role === "hr_partner") return { ok: true };
  return { ok: false, error: "Plan adaptation requires the employee's manager or an HR role." };
}

// ---------------------------------------------------------------------------
// Completion checks — pure; every gate the backend must enforce
// ---------------------------------------------------------------------------

export interface CompletionCheckInput {
  planStatus: PlanStatus;
  task: PlanTask;
  actor: { id: string; role: string; org_id: string | null };
  twin: { id: string; manager_id: string | null; org_id: string | null };
  evidence: { kind: "note" | "assessment_id"; label: string; value: string }[];
}

export function validateCompletion(i: CompletionCheckInput): { ok: boolean; code?: string; error?: string } {
  if (i.planStatus !== "approved") {
    return { ok: false, code: "plan_pending", error: "The plan must be approved by the Manager and HR Executive before tasks can be completed." };
  }
  const auth = canActOnTask(i.actor, i.task.owner_role, i.twin);
  if (!auth.ok) return { ok: false, code: "forbidden", error: auth.error };
  if (i.task.state === "done") {
    return { ok: false, code: "double_submission", error: `"${i.task.title}" is already complete — double submission rejected.` };
  }
  if (i.task.state === "waived") {
    return { ok: false, code: "already_waived", error: `"${i.task.title}" was waived — nothing to complete.` };
  }
  if (i.task.state === "failed") {
    return { ok: false, code: "task_failed", error: `"${i.task.title}" is failed/adopted out — regenerate the plan.` };
  }
  const open = i.task.blockers.filter((b) => b.status === "open");
  if (open.length > 0) {
    return { ok: false, code: "blocked", error: `Cannot complete — open blocker(s): ${open.map((b) => b.note).join("; ")}.` };
  }
  if (i.task.state === "blocked") {
    const why = i.task.blocked_reasons.length > 0 ? `Prerequisites not satisfied: ${i.task.blocked_reasons.join(", ")}` : "blocked by an upstream task or blocker";
    return { ok: false, code: "unmet_prerequisite", error: `Cannot complete — ${why}.` };
  }
  if (i.task.blocked_reasons.length > 0) {
    return { ok: false, code: "unmet_prerequisite", error: `Prerequisites not satisfied: ${i.task.blocked_reasons.join(", ")}.` };
  }
  if (i.task.state === "pending") {
    return { ok: false, code: "plan_pending", error: "The plan is not active yet." };
  }
  const missing = (i.task.evidence_requirements ?? []).filter((r) => r.required && !i.evidence.some((e) => e.kind === r.kind && String(e.value ?? "").trim().length > 0));
  if (missing.length > 0) {
    return { ok: false, code: "missing_evidence", error: `Evidence required before completion: ${missing.map((m) => m.label).join(", ")}.` };
  }
  return { ok: true };
}

// ---------------------------------------------------------------------------
// Waiver application (authorized actor/reason/policy basis/audit)
// ---------------------------------------------------------------------------

export interface WaiverInput {
  by_twin_id: string;
  by_name: string;
  reason: string;
  policy_basis: { doc_code: string; version: number | null } | null;
  at: string;
}

export function applyWaiver(task: PlanTask, waiver: WaiverInput): PlanTask {
  return {
    ...task,
    state: "waived",
    waiver: { ...waiver },
    completion_record: null,
  };
}

// ---------------------------------------------------------------------------
// Adaptation: learning -> verification, and failed verification reopens gap
// ---------------------------------------------------------------------------

export interface AdaptationInput {
  actor_twin_id: string;
  reason: string;
  source_evidence: WhyEvidence["source_evidence"];
  at: string;
}

/** Replace a learning task with a verification task (new assessment evidence). */
export function adaptLearningToVerification(defs: TaskDef[], learningTask: TaskDef, verifyDef: TaskDef, input: AdaptationInput): { defs: TaskDef[]; adaptation: Adaptation } {
  const adaptation: Adaptation = {
    kind: "replaced",
    replaced_by: verifyDef.task_code,
    reason: input.reason,
    source_evidence: input.source_evidence,
    at: input.at,
    actor_twin_id: input.actor_twin_id,
  };
  const rest = defs.filter((d) => d.task_code !== learningTask.task_code);
  return { defs: [...rest, verifyDef], adaptation };
}

/** Mark a verification task failed: the gap reopens and the plan must revise. */
export function failVerification(task: PlanTask, input: AdaptationInput): { task: PlanTask; adaptation: Adaptation } {
  const adaptation: Adaptation = {
    kind: "reopened_gap",
    reason: input.reason,
    source_evidence: input.source_evidence,
    at: input.at,
    actor_twin_id: input.actor_twin_id,
  };
  return { task: { ...task, state: "failed", adaptation }, adaptation };
}

// ---------------------------------------------------------------------------
// Plan builder — deterministic DAG from the approved role relationship
// ---------------------------------------------------------------------------

export interface PlanBuildInput {
  role: {
    title: string;
    required_skills: { skill: string; target_proficiency: number }[];
    future_skills: { skill: string; target_proficiency: number }[];
    seniority_level: number;
  };
  verified_skills: { name: string; proficiency: number }[];
  policy_docs: { doc_code: string; title: string }[];
  reopened_skills?: string[]; // skills whose verification failed — learn again
}

const slug = (s: string) => s.trim().toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "");

function skillProficiency(verified: { name: string; proficiency: number }[], skill: string): number {
  const hit = verified.find((v) => v.name.toLowerCase() === skill.toLowerCase());
  return hit?.proficiency ?? 0;
}

/**
 * Deterministic plan: core provisioning/policy/admin + skill-gap learning tasks
 * + one verification task on the first required-skill gap + survey.
 */
export function buildPlanDefs(input: PlanBuildInput): TaskDef[] {
  const required = (input.role.required_skills ?? []).slice(0, 3);
  const future = (input.role.future_skills ?? []).slice(0, 2);
  const reopened = new Set((input.reopened_skills ?? []).map((s) => s.toLowerCase()));

  const gaps = required.filter(
    (s) => reopened.has(s.skill.toLowerCase()) || skillProficiency(input.verified_skills, s.skill) < s.target_proficiency
  );
  const futureGaps = future.filter((s) => skillProficiency(input.verified_skills, s.skill) < s.target_proficiency);

  const secPolicy = input.policy_docs.find((p) => p.doc_code === "POL-SEC");
  const defs: TaskDef[] = [
    {
      task_code: "it_provisioning",
      title: "IT & Laptop Provisioning",
      task_type: "provisioning",
      owner_role: "it_security",
      required: true,
      non_waivable: true,
      depends_on: [],
      duration_days: 1,
      why_evidence: {
        reason: "Company-issued equipment is mandatory before any system access is granted.",
        source_evidence: [{ source_type: "policy", fact: secPolicy ? `POL-SEC ${secPolicy.title} — work on company-issued devices only.` : "Equipment & Security policy — company-issued devices only." }],
      },
      evidence_requirements: [{ kind: "note", label: "Hardware & asset tag", required: true }],
    },
    {
      task_code: "security_training",
      title: "Security & Compliance Training",
      task_type: "policy",
      owner_role: "employee",
      required: true,
      non_waivable: true,
      depends_on: [],
      duration_days: 1,
      why_evidence: {
        reason: "Annual security training is required for continued system access.",
        source_evidence: [{ source_type: "policy", fact: secPolicy ? `POL-SEC ${secPolicy.title} — annual training required.` : "Equipment & Security policy — annual training required." }],
      },
      evidence_requirements: [{ kind: "note", label: "Training completion reference", required: true }],
    },
    {
      task_code: "payroll",
      title: "Direct Deposit & Payroll Setup",
      task_type: "onboarding_admin",
      owner_role: "hr",
      required: true,
      non_waivable: true,
      depends_on: [],
      duration_days: 0.5,
      why_evidence: {
        reason: "Payroll setup is handled by HR before the first pay run.",
        source_evidence: [{ source_type: "onboarding_admin", fact: "Standard onboarding payroll step." }],
      },
      evidence_requirements: [{ kind: "note", label: "Payroll reference (HR)", required: true }],
    },
    {
      task_code: "access_sso",
      title: "System Access & SSO Enrollment",
      task_type: "access",
      owner_role: "it_security",
      required: true,
      non_waivable: true,
      depends_on: ["it_provisioning", "security_training"],
      duration_days: 0.5,
      why_evidence: {
        reason: "SSO and tool access can only be provisioned after hardware and security training are complete.",
        source_evidence: [{ source_type: "policy", fact: "POL-SEC — MFA mandatory on all accounts; access requires completed security training." }],
      },
      evidence_requirements: [{ kind: "note", label: "MFA / SSO enrollment reference", required: true }],
    },
    {
      task_code: "team_intro",
      title: "Team Introduction & Codebase Walkthrough",
      task_type: "onboarding_admin",
      owner_role: "manager",
      required: true,
      non_waivable: false,
      depends_on: ["access_sso"],
      duration_days: 1,
      why_evidence: {
        reason: "Manager-led introduction and codebase walkthrough require system access first.",
        source_evidence: [{ source_type: "manager", fact: "Standard team integration step after access." }],
      },
      evidence_requirements: [{ kind: "note", label: "Walkthrough held (manager)", required: true }],
    },
  ];

  const firstGap = gaps[0];
  for (const s of gaps) {
    const isReopened = reopened.has(s.skill.toLowerCase());
    const code = isReopened ? `learn_${slug(s.skill)}_reopen` : `learn_${slug(s.skill)}`;
    defs.push({
      task_code: code,
      title: isReopened ? `Re-learning: ${s.skill} (verified gap re-opened)` : `First contribution using ${s.skill}`,
      task_type: "learning",
      owner_role: "employee",
      required: true,
      non_waivable: false,
      depends_on: ["team_intro"],
      duration_days: 1,
      why_evidence: {
        reason: isReopened
          ? `A prior verification attempt did not confirm ${s.skill} at target ${s.target_proficiency}; the gap is re-opened for learning.`
          : `Role requires ${s.skill} at ${s.target_proficiency}; current verified proficiency is ${skillProficiency(input.verified_skills, s.skill)}.`,
        source_evidence: [
          { source_type: "role_fit", fact: `Gap on ${s.skill} vs approved role ${input.role.title} (target ${s.target_proficiency}).` },
          ...(isReopened ? [{ source_type: "verification", fact: `Previous verification of ${s.skill} failed — reason preserved on the superseded task.` }] : []),
        ],
      },
      evidence_requirements: [{ kind: "note", label: `Contribution evidence: ${s.skill}`, required: true }],
    });
    // Verification task on the FIRST gap only.
    if (firstGap && s.skill.toLowerCase() === firstGap.skill.toLowerCase()) {
      defs.push({
        task_code: `verify_${slug(s.skill)}`,
        title: `Verification: ${s.skill} mastery assessment`,
        task_type: "verification",
        owner_role: "employee",
        required: true,
        non_waivable: false,
        depends_on: [code],
        duration_days: 0.5,
        why_evidence: {
          reason: `New assessment evidence replaces further learning for ${s.skill}: verify mastery at target ${s.target_proficiency}.`,
          source_evidence: [{ source_type: "assessment", fact: `Assessment evidence supersedes the learning-only path for ${s.skill}.` }],
        },
        evidence_requirements: [{ kind: "assessment_id", label: "Assessment evidence id", required: true }],
      });
    }
  }
  for (const s of futureGaps) {
    const anchor = gaps[0] ? `learn_${slug(gaps[0].skill)}` : "team_intro";
    defs.push({
      task_code: `future_${slug(s.skill)}`,
      title: `Upskilling plan: ${s.skill}`,
      task_type: "learning",
      owner_role: "employee",
      required: true,
      non_waivable: false,
      depends_on: [anchor],
      duration_days: 1,
      why_evidence: {
        reason: `Future skill ${s.skill} is part of the role's growth path; current verified proficiency ${skillProficiency(input.verified_skills, s.skill)} is below target ${s.target_proficiency}.`,
        source_evidence: [{ source_type: "role_fit", fact: `Future-fit gap on ${s.skill} vs approved role ${input.role.title}.` }],
      },
      evidence_requirements: [{ kind: "note", label: `Upskilling evidence: ${s.skill}`, required: true }],
    });
  }
  defs.push({
    task_code: "survey",
    title: "Onboarding Feedback Survey",
    task_type: "onboarding_admin",
    owner_role: "employee",
    required: true,
    non_waivable: false,
    depends_on: [gaps.length > 0 ? `learn_${slug(gaps[0].skill)}` : "team_intro"],
    duration_days: 0.5,
    why_evidence: {
      reason: "Feedback survey closes the loop after the core journey is underway.",
      source_evidence: [{ source_type: "onboarding_admin", fact: "Standard closing step." }],
    },
    evidence_requirements: [{ kind: "note", label: "Survey submitted", required: true }],
  });
  return defs;
}

// ---------------------------------------------------------------------------
// Carryover on regeneration: preserve valid completed work with a mapping
// ---------------------------------------------------------------------------

export function buildCarryover(prevTasks: PlanTask[], newDefs: TaskDef[], fromPlanId: string, fromVersion: number): { tasks: PlanTask[]; entries: CarryoverEntry[] } {
  const byCode = new Map(prevTasks.map((t) => [t.task_code, t]));
  const entries: CarryoverEntry[] = [];
  const tasks: PlanTask[] = newDefs.map((d) => {
    const prev = byCode.get(d.task_code);
    const fresh: PlanTask = { ...d, state: "pending", start_date: null, due_date: null, topological_level: 0, blocked_reasons: [], blockers: [], waiver: null, completion_record: null, adaptation: null };
    if (!prev) return fresh;
    const defSame =
      prev.title === d.title &&
      prev.task_type === d.task_type &&
      prev.owner_role === d.owner_role &&
      prev.required === d.required &&
      prev.non_waivable === d.non_waivable &&
      prev.duration_days === d.duration_days &&
      JSON.stringify([...prev.depends_on].sort()) === JSON.stringify([...d.depends_on].sort());
    if (!defSame) return fresh;
    if (prev.state === "done" && prev.completion_record) {
      entries.push({ task_code: d.task_code, from_version: fromVersion, from_plan_id: fromPlanId, note: "Completed work preserved on regeneration." });
      return { ...d, state: "done", start_date: prev.start_date, due_date: prev.due_date, topological_level: 0, blocked_reasons: [], blockers: [], waiver: prev.waiver, completion_record: prev.completion_record, adaptation: prev.adaptation };
    }
    if (prev.state === "waived" && prev.waiver) {
      entries.push({ task_code: d.task_code, from_version: fromVersion, from_plan_id: fromPlanId, note: "Waiver preserved on regeneration." });
      return { ...d, state: "waived", start_date: prev.start_date, due_date: prev.due_date, topological_level: 0, blocked_reasons: [], blockers: [], waiver: prev.waiver, completion_record: null, adaptation: prev.adaptation };
    }
    return fresh;
  });
  return { tasks, entries };
}


import { createClient } from "https://esm.sh/@supabase/supabase-js@2.39.0";



const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), { status, headers: { ...corsHeaders, "Content-Type": "application/json" } });

async function isTeamMember(supabase, rootTwinId: string, checkTwinId: string): Promise<boolean> {
  const { data } = await supabase.from("digital_twins").select("id, manager_id");
  const children = new Map<string, string[]>();
  for (const t of data ?? []) {
    if (t.manager_id) children.set(t.manager_id, [...(children.get(t.manager_id) ?? []), t.id]);
  }
  const seen = new Set<string>();
  const stack = [rootTwinId];
  while (stack.length > 0) {
    const cur = stack.pop()!;
    if (seen.has(cur)) continue;
    seen.add(cur);
    for (const c of children.get(cur) ?? []) stack.push(c);
  }
  return seen.has(checkTwinId);
}

function taskRow(planId: string, t: PlanTask) {
  return {
    org_id: null, // filled by caller
    plan_id: planId,
    version: null, // filled by caller
    task_code: t.task_code,
    title: t.title,
    task_type: t.task_type,
    owner_role: t.owner_role,
    required: t.required,
    non_waivable: t.non_waivable,
    depends_on: t.depends_on,
    duration_days: t.duration_days,
    due_date: t.due_date,
    topological_level: t.topological_level,
    why_evidence: t.why_evidence,
    evidence_requirements: t.evidence_requirements,
    state: t.state,
    completion_record: t.completion_record,
    blockers: t.blockers,
    waiver: t.waiver,
    adaptation: t.adaptation,
  };
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response("ok", { headers: corsHeaders });

  const supabase = createClient(
    Deno.env.get("SUPABASE_URL")!,
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!
  );

  const authHeader = req.headers.get("Authorization") ?? "";
  const { data: userData } = await supabase.auth.getUser(authHeader.replace("Bearer ", ""));
  const uid = userData?.user?.id;
  if (!uid) return json({ error: "UNAUTHENTICATED" }, 401);

  const { data: caller } = await supabase
    .from("digital_twins")
    .select("id, role, email, org_id")
    .eq("auth_user_id", uid)
    .maybeSingle();
  if (!caller) return json({ error: "UNAUTHENTICATED" }, 401);

  let body: { twin_id?: string; regen?: boolean; start_date?: string } = {};
  try {
    body = await req.json();
  } catch {
    /* empty */
  }
  const twinId = (body.twin_id ?? "").trim();
  if (!twinId) return json({ error: "VALIDATION_ERROR", message: "twin_id is required." }, 400);

  const { data: twin, error: twinErr } = await supabase
    .from("digital_twins")
    .select("id, org_id, role, name, job_title, verified_skills, seniority_level, computed_fits, audit_events, manager_id")
    .eq("id", twinId)
    .maybeSingle();
  if (twinErr || !twin) return json({ error: "NOT_FOUND" }, 404);

  // Visibility: HR/partner see anyone; manager sees team + self; employee self only; IT sees all org (service view).
  let allowed = false;
  if (["hr_executive", "hr_partner", "it_security"].includes(caller.role)) allowed = twin.org_id === caller.org_id;
  else if (caller.role === "manager" || caller.role === "employee") {
    allowed = twin.id === caller.id || (caller.role === "manager" && (await isTeamMember(supabase, caller.id, twin.id)));
  }
  if (!allowed) return json({ error: "FORBIDDEN" }, 403);

  // -------------------------------------------------------------------------
  // Approved role relationship: the employee's SELECTED application binds the
  // plan to a real requisition. NEVER a title substring match.
  // -------------------------------------------------------------------------
  const { data: appRows } = await supabase
    .from("applications")
    .select("id, requisition_id, stage")
    .eq("org_id", twin.org_id)
    .eq("candidate_twin_id", twinId)
    .eq("stage", "selected")
    .order("applied_at", { ascending: false })
    .limit(5);
  const approvedApp = (appRows ?? []).find((a) => a.stage === "selected");
  if (!approvedApp) {
    return json(
      { error: "NO_APPROVED_ROLE", message: "No approved application (selected role) is on file for this employee. Plans are built from the approved role relationship only — not from a title guess." },
      400
    );
  }

  const { data: reqRow } = await supabase
    .from("job_requisitions")
    .select("id, title, required_skills, future_skills, seniority_level")
    .eq("id", approvedApp.requisition_id)
    .maybeSingle();
  if (!reqRow) return json({ error: "NOT_FOUND", message: "Approved requisition not found." }, 404);

  const { data: polRows } = await supabase
    .from("policy_documents")
    .select("doc_code, title")
    .eq("org_id", twin.org_id);
  const policyDocs = (polRows ?? []) as { doc_code: string; title: string }[];

  const { data: graphRows } = await supabase
    .from("skill_graph")
    .select("skill, category, outgoing_edges")
    .eq("org_id", twin.org_id);

  const now = new Date().toISOString();
  const startDate = body.start_date ?? now;

  // Fit context (informational — the plan itself is built from gaps).
  const fitCurrent = computeFit({
    candidateSkills: (twin.verified_skills ?? []) as { name: string; proficiency: number; evidence_source: string; verification_rigor: "low" | "medium" | "high" }[],
    candidateLevel: twin.seniority_level ?? 3,
    requiredSkills: (reqRow.required_skills ?? []) as { skill: string; target_proficiency: number }[],
    roleLevel: reqRow.seniority_level ?? 3,
    skillGraph: graphRows ?? [],
    target: { type: "requisition", id: reqRow.id, title: reqRow.title },
    scenario: "current",
    computedAt: now,
  });

  const defs: TaskDef[] = buildPlanDefs({
    role: reqRow,
    verified_skills: (twin.verified_skills ?? []) as { name: string; proficiency: number }[],
    policy_docs: policyDocs,
  });
  const hash = planHash(defs);

  // Latest plan for the twin (any status) — for carryover + supersession.
  const { data: prevPlans } = await supabase
    .from("onboarding_plans")
    .select("id, version, status")
    .eq("org_id", twin.org_id)
    .eq("twin_id", twinId)
    .order("version", { ascending: false })
    .limit(1);
  const prevPlan = (prevPlans ?? [])[0];

  // A plain build (no regen) with an existing non-superseded plan is a no-op —
  // version churn only happens on explicit regeneration.
  if (prevPlan && prevPlan.status !== "superseded" && body.regen !== true) {
    const { data: noopTasks } = await supabase
      .from("onboarding_tasks")
      .select("task_code, title, task_type, owner_role, required, non_waivable, depends_on, duration_days, due_date, topological_level, why_evidence, evidence_requirements, state, completion_record, blockers, waiver, adaptation")
      .eq("plan_id", prevPlan.id)
      .order("topological_level", { ascending: true });
    return json({
      ok: true,
      plan: {
        id: prevPlan.id,
        twin_id: twinId,
        version: prevPlan.version,
        plan_hash: (prevPlan as unknown as { plan_hash?: string }).plan_hash ?? hash,
        status: prevPlan.status,
        start_date: startDate,
        generated_at: now,
        readiness: (prevPlan as unknown as { readiness?: unknown }).readiness ?? {},
        carryover: (prevPlan as unknown as { carryover?: unknown[] }).carryover ?? [],
        requisition: { id: reqRow.id, title: reqRow.title },
        fit_current: fitCurrent.score,
        tasks: (noopTasks ?? []) as unknown[],
      },
    });
  }

  let tasks: PlanTask[] = deriveStates(defs, { approved: false, startDate });
  let carryover: { task_code: string; from_version: number; from_plan_id: string; note: string }[] = [];
  let version = 1;

  if (prevPlan) {
    const { data: prevTaskRows } = await supabase
      .from("onboarding_tasks")
      .select("*")
      .eq("plan_id", prevPlan.id);
    const prevTasks = (prevTaskRows ?? []) as unknown[];
    const mapped: PlanTask[] = (prevTasks as {
      task_code: string; title: string; task_type: string; owner_role: string; required: boolean;
      non_waivable: boolean; depends_on: string[]; duration_days: number; why_evidence: unknown;
      evidence_requirements: unknown[]; state: string; completion_record: unknown; blockers: unknown[];
      waiver: unknown; adaptation: unknown;
    }[]).map((r) => ({
      task_code: r.task_code,
      title: r.title,
      task_type: r.task_type as PlanTask["task_type"],
      owner_role: r.owner_role as PlanTask["owner_role"],
      required: r.required,
      non_waivable: r.non_waivable,
      depends_on: r.depends_on ?? [],
      duration_days: Number(r.duration_days),
      why_evidence: r.why_evidence as PlanTask["why_evidence"],
      evidence_requirements: (r.evidence_requirements ?? []) as PlanTask["evidence_requirements"],
      state: r.state as PlanTask["state"],
      start_date: null,
      due_date: null,
      topological_level: 0,
      blocked_reasons: [],
      blockers: (r.blockers ?? []) as PlanTask["blockers"],
      waiver: r.waiver as PlanTask["waiver"],
      completion_record: r.completion_record as PlanTask["completion_record"],
      adaptation: r.adaptation as PlanTask["adaptation"],
    }));

    const carried = buildCarryover(mapped, defs, prevPlan.id, prevPlan.version);
    tasks = carried.tasks;
    carryover = carried.entries;
    version = prevPlan.version + 1;
  }

  // Recompute the full scheduled view (dates/levels/states) from the defs.
  const done = tasks.filter((t) => t.state === "done").map((t) => t.task_code);
  const waived = tasks.filter((t) => t.state === "waived").map((t) => t.task_code);
  const blockers: Record<string, PlanTask["blockers"]> = {};
  for (const t of tasks) if (t.blockers.length > 0) blockers[t.task_code] = t.blockers;
  const derived = materialize(
    deriveStates(defs, { approved: true, startDate, done, waived, blockers }),
    { completion: Object.fromEntries(tasks.filter((t) => t.completion_record).map((t) => [t.task_code, t.completion_record!])),
      waiver: Object.fromEntries(tasks.filter((t) => t.waiver).map((t) => [t.task_code, t.waiver!])),
      blockers }
  );
  tasks = derived;
  const readiness = estimateReadiness(defs, tasks, startDate, now);

  // Supersede any prior plan — old approvals never carry (no retained approved state).
  if (prevPlan && prevPlan.status !== "superseded") {
    await supabase
      .from("onboarding_plans")
      .update({ status: "superseded", audit_events: [...((prevPlan as unknown as { audit_events?: unknown[] }).audit_events ?? []), { actor: caller.email ?? uid, action: "superseded_by_regeneration", note: `Superseded by plan v${version}.`, timestamp: now }] })
      .eq("id", prevPlan.id);
  }

  const planRow = {
    org_id: twin.org_id,
    twin_id: twinId,
    application_id: approvedApp.id,
    version,
    plan_hash: hash,
    status: "pending_approval",
    manager_approval: null,
    hr_approval: null,
    start_date: startDate,
    generated_at: now,
    readiness,
    carryover,
    audit_events: [
      { actor: caller.email ?? uid, action: prevPlan ? "plan_regenerated" : "plan_generated", note: `Plan v${version} built from approved role "${reqRow.title}" — ${defs.length} tasks, ${carryover.length} carried.`, timestamp: now },
    ],
  };
  const { data: inserted, error: insErr } = await supabase
    .from("onboarding_plans")
    .insert(planRow)
    .select("id")
    .single();
  if (insErr || !inserted) return json({ error: "INTERNAL", message: insErr?.message ?? "plan insert failed" }, 500);
  const planId = inserted.id;

  const { error: taskErr } = await supabase
    .from("onboarding_tasks")
    .insert(tasks.map((t) => ({ ...taskRow(planId, t), org_id: twin.org_id, version })));
  if (taskErr) {
    await supabase.from("onboarding_plans").delete().eq("id", planId);
    return json({ error: "INTERNAL", message: taskErr.message }, 500);
  }

  // Persist fits + audit on the twin.
  const fits = (twin.computed_fits ?? []) as { target_id: string; scenario: string }[];
  const nextFits = [...fits.filter((f) => !(f.target_id === reqRow.id && f.scenario === "current")), fitCurrent as unknown as { target_id: string; scenario: string }];
  await supabase
    .from("digital_twins")
    .update({
      computed_fits: nextFits,
      audit_events: [
        ...(twin.audit_events ?? []),
        { actor: caller.email ?? uid, action: "plan_fit_computed", note: `Role fit current ${fitCurrent.score.toFixed(2)}.`, timestamp: now },
      ],
    })
    .eq("id", twinId);

  return json({
    ok: true,
    plan: {
      id: planId,
      twin_id: twinId,
      version,
      plan_hash: hash,
      status: "pending_approval",
      start_date: startDate,
      generated_at: now,
      readiness,
      carryover,
      requisition: { id: reqRow.id, title: reqRow.title },
      fit_current: fitCurrent.score,
      tasks,
    },
  });
});
